using Godot;
using System;
using GArray=Godot.Collections.Array;
public partial class ActorDefinitionOperations
{
    private static Variant CatalogValue(Resource? value)=>value==null?default:Variant.From(value);
    private static GDScript Module(string path)=>GD.Load<GDScript>("res://"+path+".gd");
    public bool register_basic_actors(RefCounted registry)
    {
        var catalog=ResourceLoader.Load("res://scripts/actors/examples/basic_actor_catalog.tres","",ResourceLoader.CacheMode.Reuse);if(catalog==null)return false;bool ok=true;foreach(var value in catalog.Get("object_definitions").AsGodotArray())ok=register_object(registry,value.As<Resource>())&&ok;foreach(var value in catalog.Get("definitions").AsGodotArray())ok=register(registry,value.As<Resource>())&&ok;
        ok=register_object(registry,Module("scripts/actors/physics/powder/powder_material").Call("definition").As<Resource>())&&register_object(registry,Module("scripts/actors/physics/destruction/destruction_material").Call("definition").As<Resource>())&&register_object(registry,Module("scripts/actors/physics/destruction/destruction_material").Call("region_definition").As<Resource>())&&register(registry,Module("scripts/actors/physics/fluid/fluid_definition").Call("create").As<Resource>())&&register(registry,Module("scripts/actors/physics/powder/powder_definition").Call("create").As<Resource>())&&ok;
        if(get_definition(registry,new StringName("environment_asset"))==null)ok=register(registry,Module("Workspaces/EnvironmentWorkspace/environment_actor_definition").Call("create",CatalogValue(get_definition(registry,new StringName("point_3d")))).As<Resource>())&&ok;
        foreach(var value in get_definitions(registry)){var definition=value.As<Resource>();foreach(string path in new[]{"scripts/actors/physics/destruction/destruction_definition","scripts/actors/physics/structure/structure_definition","scripts/actors/physics/destruction/debris_definition","scripts/actors/physics/destruction/destruction_authoring","Workspaces/ModelWorkspace/growth/growth_actor","scripts/actors/fog/fog_actor","scripts/actors/fog/fog_motion_definition","scripts/actors/fog/fog_lighting"})Module(path).Call("extend_actor",definition);}
        Module("scripts/actors/fog/fog_lighting").Call("extend_environment",CatalogValue(get_object_definition(registry,new StringName("environment"))));foreach(var entry in new[]{("scripts/actors/fog/fog_appearance","definition"),("scripts/actors/fog/fog_field","definition"),("scripts/actors/fog/fog_motion_definition","emitter_definition"),("scripts/actors/fog/fog_motion_definition","velocity_definition")})ok=register_object(registry,Module(entry.Item1).Call(entry.Item2).As<Resource>())&&ok;
        if(get_definition(registry,new StringName("global_fog"))==null)ok=register(registry,Module("scripts/actors/fog/fog_actor").Call("global_definition",CatalogValue(get_definition(registry,new StringName("fog_volume")))).As<Resource>())&&ok;ok=register_object(registry,Module("scripts/actors/physics/destruction/debris_definition").Call("preset_definition").As<Resource>())&&ok;ok=register_object(registry,Module("scripts/actors/physics/destruction/destruction_authoring").Call("definition").As<Resource>())&&ok;
        foreach(string type in new[]{"material","shader_material","natural_material"}){var definition=get_object_definition(registry,new StringName(type));if(definition!=null&&find_property(definition,new StringName("damage_material"))==null){var property=_properties.create(new StringName("damage_material"),"Associated physical damage material",default,false);property.Set("object_type",new StringName("destruction_material"));property.Get("options").AsGodotDictionary()["group"]="Physical association";definition.Get("properties").AsGodotArray().Add(property);}}return ok;
    }
}
